    # Connect diagonally aligned 1 markers, preserving 6 markers along the way.
    for i, (r1,c1) in enumerate(ones):
        for r2,c2 in ones[i+1:]:
            dr, dc = r2-r1, c2-c1
            if abs(dr) == abs(dc) and dr != 0:
                sr, sc = (1 if dr>0 else -1), (1 if dc>0 else -1)
                r,c=r1,c1
                while True:
                    if out[r][c] != 6:
